{
  "findings": [
    {
      "ref": "[D534]",
      "area": "contact",
      "claim": "A parent reports that strangers can send friend requests and messages, and these cannot be disabled.",
      "stance": "risk",
      "quote": "you also can't disable Friend requests."
    },
    {
      "ref": "[D534]",
      "area": "contact",
      "claim": "A parent reports that unwanted interactions with strangers can occur and must be ignored.",
      "stance": "risk",
      "quote": "you need to click ignore in the game to do away with them"
    },
    {
      "ref": "[D534]",
      "area": "money",
      "claim": "A parent reports that Roblox uses in-app purchases to buy gear and vehicles, incentivizing children to pay.",
      "stance": "risk",
      "quote": "children are incentivized to pay for these and to ask for more roblox money"
    },
    {
      "ref": "[D534]",
      "area": "data",
      "claim": "A parent reports that age is entered to enable safe-chat mode, but it does not filter games.",
      "stance": "neutral",
      "quote": "their age however does not filter the content in the games"
    },
    {
      "ref": "[D534]",
      "area": "age_gating",
      "claim": "A parent reports that age gating only enables safe-chat mode and does not restrict game access.",
      "stance": "risk",
      "quote": "their age does not feel to the types of games they can play on roblox"
    },
    {
      "ref": "[D534]",
      "area": "content",
      "claim": "A parent reports that horror, violent, and bloody games like Hotline Roblox exist and are not filtered by the rating.",
      "stance": "risk",
      "quote": "there are games on the system that have intentionally correlated violent or bloody themes and these are not provided in the original downloads"
    },
    {
      "ref": "[D534]",
      "area": "developer_record",
      "claim": "A parent reports that Roblox has been rated by PEGI and ESRB with warnings about user-generated content.",
      "stance": "neutral",
      "quote": "the Video Standards Council expanded on the PEGI rating by saying, \"Violence is very mild and consists of blocky, action-figure and stick-like humanoid characters competing in various child-friendly games. Armed with fists, swords or guns they can hit each other until they fall apart and disappear. Blood and injuries are not depicted.\""
    }
  ]
}
